std::string id() const;         // 适配器唯一 id
std::string name() const;       // 显示名
std::string platform() const;   // 平台标识，如 "onebot_v11"
std::string version() const;

bool configure(const json& config);   // 配置（endpoint / token 等）
bool start();                         // 连接平台
void stop();                          // 断开并释放资源
bool isConnected() const;
std::string lastError() const;
std::string getLoginId() const;       // 登录账号
std::string getLoginName() const;

另有可覆写的 connectionStatus()（细粒度状态，含 "timeout" 重连退避暂停态）与 resumeConnection()（手动恢复，WebUI「重连」按钮调用）。

void sendMessage(const Message& msg);                       // 必须实现
void sendReply(const Message& original, const std::string& replyText);
void onMessage(MessageCallback cb);                          // 消息回调注册
void onEvent(EventCallback cb);                              // 通知/请求事件（默认空）

// 以下默认空实现 / 回退，按平台能力覆写：
void sendGroupMessage(groupId, text);        // 网页后台发群消息
void sendGroupMessageCQ(groupId, cqText);    // 文本含 CQ 码（[CQ:at,..]/[CQ:image,..]），默认回退纯文本
void sendPrivateMessage(userId, text);
bool sendGroupForwardMsg(groupId, nodes);    // 合并转发，false = 不支持（调用方回退分段）
void sendGroupPoke(groupId, userId);         // 戳一戳

// 默认空/未知，按需覆写：
std::vector> getGroupList() const;  // (id, 名称)
int getGroupMemberCount(groupId) const;
std::string getSelfRole(groupId) const;      // 骰娘自身角色 "owner"|"admin"|"member"
json getMembers(groupId) const;              // 成员列表缓存（平台原生对象）
int getFriendCount() const;                  // -1 = 未知
std::vector getFriendList() const;
void deleteFriend(userId);
void refreshGroupList() / refreshSelfRole(groupId) / refreshMembers(groupId);  // 异步刷新
void requestGroupHistory(groupId, count);    // 历史消息（结果以 kGroupHistory 事件上抛）

// 上传群文件（.log end 传日志 txt）。content = 原始字节，兼容远程/容器化协议端。
void uploadGroupFile(groupId, name, content, localPath = "");

// 同步调用平台 API 并等待响应（群文件列表/下载链等请求-响应式接口）。
// ⚠️ 不得在适配器接收线程上调用（会死锁）；供 WebUI 的 drogon 处理线程使用。
json invokeAction(action, params, timeoutMs = 8000);

struct Message {
    std::string id;             // 消息唯一 ID
    std::string platform;       // 来源平台（用于 i18n 语言解析）
    std::string content;        // 纯文本（已去 CQ 码，用于指令解析）
    std::string rawContent;     // 原始消息（CQ 码原样）
    std::string displayContent; // 可读形式（文字/@xxx/[图片]…），用于日志/模拟聊天
    std::string senderId, senderName;
    std::string targetId;       // 群号（私聊为对方 id）
    std::string selfId;         // 收到此消息的机器人账号（多骰娘定向）
    std::string adapterId;      // 接收适配器 id（回执/平台操作定位用）
    std::vector atList;  // 被 @ 的账号（"all" = @全体）
    MessageType type;
    int64_t timestamp;
    bool fromSelf;              // 骰娘账号自身发出（自控开关）
    json extra;                 // 平台附加数据
};

enum class EventType {
    kGroupIncrease, kGroupDecrease,   // 入群 / 退群·被踢
    kFriendAdd, kFriendRequest, kGroupRequest,
    kPoke,                            // 戳一戳
    kGroupRecall,                     // 群消息撤回
    kGroupHistory,                    // 历史消息拉取结果
    kGroupUpload,                     // 群文件上传
    kOther,
};

事件通过 BotEvent（含 flag / subType / operatorId 等字段）经 onEvent 回调上抛，供审批策略、自定义回复与通知系统消费。

适配器由 AdapterManager 统一管理：

auto adapter = std::make_shared(/* id */);
adapter->configure({ {"name", "MyBot"}, {"endpoint", "..."} });
adapterMgr.registerAdapter(adapter);
// AdapterManager 会把各适配器的消息 / 事件统一分发给上层处理

const before = seal.favor.get(ctx);
const after = seal.favor.add(ctx, 5);
const growth = seal.favor.grow(ctx);
seal.replyToSender(ctx, msg,
  好感：${before} → ${after}\n成长：${growth.success ? +${growth.delta} : '未成长'});

传入第三方平台的用户 ID 时必须使用该平台原始字符串 ID，不能假定所有账号都是数字 QQ。目标 userId 或上下文平台缺失时返回 null，且不会写入数据。

const resp = await fetch(url, { method: 'POST', headers: {...}, body: {...} });
// resp.ok / resp.status / await resp.text() / await resp.json()

受安全门控：需要在管理面板「系统设置」打开外置 API 开关并把目标域名加入白名单，否则请求会被拒绝（Promise reject）。body 传对象会自动 JSON 序列化。另有 btoa/atob 全局函数。

同步实现
fetch 底层是同步阻塞的，慢接口会拖住消息处理——对时效不敏感的请求放进定时器回调更稳妥。

const ext = seal.ext.new('api-example', 'Dice!Next', '1.0.0');
const cmd = seal.ext.newCmdItemInfo();
cmd.name = '卡片示例';
cmd.help = '读取群名片和侦查值';
cmd.solve = (ctx, msg) => {
  const card = ctx.player.card || '未设群名片';
  const [spot, exists] = seal.vars.intGet(ctx, '侦查');
  seal.replyToSender(ctx, msg, ${ctx.player.name}（${card}）\n侦查：${exists ? spot : '未记录'});
  return seal.ext.newCmdExecuteResult(true);
};
ext.cmdMap['卡片示例'] = cmd;
seal.ext.register(ext);

每个文件在干净的全局 msg_reply 表里执行，之后枚举其中的规则：

msg_reply['好感'] = {
  keyword = { match = { '{自称}好感' } },   -- 也可用 prefix / search
  limit = { cd = 10, user_var = { trust = { at_least = 0 } } },
  echo = function(msg)
    local favor = getUserConf(msg.uid, '&favor', 0)
    return '当前好感度：' .. favor
  end,
}

| 字段 | 说明 |

普通文案、原生自定义回复、文件牌堆与 Lua speech 共用安全文本函数：sample、case、grade、ran、len、expired、var、at、print、wait。不执行模板内的 JS / Python，不通过模板读写宿主配置或文件；wait 走异步等待，不让消息线程休眠。各入口可读字段仍取决于它的消息上下文，预览不会等待或发送消息。

{var:本次={ran:1~100}}本次是 {本次}，再显示仍是 {本次}
{case:user.trust?0=用户&else=受信用户}
{grade:user.favor?0=普通&100=亲密&else=未知}

{var:名?值} 赋值并显示，{var:名=值&另一名=值} 只赋值；仅本次渲染有效，不能用点路径修改人物卡、用户数据或权限。ran 接受有序整数上下界（含端点），expired 判断字段中的整数 Unix 时间是否已经过去（缺失或无效视为过期）。随机文本与游戏骰点独立。

len 对字符串返回 UTF-8 字节数；Lua 消息中的 Set / 普通表返回元素数，不调用 __len / __pairs，数值、布尔值返回 0。普通指令文案和牌堆也可用 {len:game.pls} / {len:game.gms} 查看当前团的玩家 / GM 人数；局部变量依然是字符串。集合长度检查有工作量上限，不等于开放任意对象序列化。

新建 hello.js：

// ==UserScript==
// @name         打招呼
// @author       希亚
// @version      1.0.0
// @description  示例插件：.hello 会回复问候
// ==/UserScript==

const ext = seal.ext.new('hello', '希亚', '1.0.0');

const cmd = seal.ext.newCmdItemInfo();
cmd.name = 'hello';
cmd.help = '.hello // 骰娘向你问好';
cmd.solve = (ctx, msg, cmdArgs) => {
  seal.replyToSender(ctx, msg, 你好，${ctx.player.name}！今天也要好好跑团哦。);
  return seal.ext.newCmdExecuteResult(true);
};

ext.cmdMap['hello'] = cmd;
seal.ext.register(ext);

头部的 // @name 等 UserScript 注释是插件元数据（管理面板会显示；同名插件按 @version 取最高版本）。

下面每段都是可以直接抄的完整片段，细节见 JS 插件 API 参考。

读写持久化数据（重启不丢，存放在 data/plugins.db）：

ext.storageSet('count', String(Number(ext.storageGet('count') || '0') + 1));

读写玩家人物卡（与 .st 是同一份卡）：

const [hp, ok] = seal.vars.intGet(ctx, 'hp');   // 无 $ 前缀 = 人物卡属性
seal.vars.intSet(ctx, 'hp', hp - 1);
const [note] = seal.vars.strGet(ctx, '$m备注');  // $m=个人 $g=群 $=全局 变量

