cmd.solve = (ctx, msg, cmdArgs) => {
  const who = cmdArgs.getArgN(1);            // 第 1 个参数
  const rest = cmdArgs.getRestArgsFrom(2);   // 第 2 个起的剩余文本
  const at = cmdArgs.at[0];                  // 消息里 @ 的人 {userId}
  // ...
};

定时任务（每天固定时刻执行）：

seal.ext.registerTask(ext, 'daily', '08:30', () => {
  // 这里 replyToSender 需要你自己保存的 ctx/msg，或使用群号直发
}, 'morning', '早安提醒');

联网（需在管理面板「系统设置」开启外置 API 开关并配置白名单）：

const resp = await fetch('https://api.example.com/data');
const data = await resp.json();

给插件加 WebUI 配置项（用户不用改代码就能调参数）：

seal.ext.registerStringConfig(ext, '问候语', '今天也要好好跑团哦', '打招呼的后半句');
// solve 里读取：
const greeting = seal.ext.getStringConfig(ext, '问候语');

想让插件响应普通聊天（不带 . 前缀），实现 ext.onNotCommandReceived：

ext.onNotCommandReceived = (ctx, msg) => {
  if (msg.message.includes('骰娘晚安')) {
    seal.replyToSender(ctx, msg, '晚安，好梦～');
  }
};

使用已登录的后台会话，或后台配置的 X-API-Key，访问：

GET /api/adapters/{adapterId}/qq-official-actions
POST /api/adapters/{adapterId}/qq-official-actions

GET 返回当前账号支持的 actions 和 capabilities。POST 请求固定为以下结构；这是后台接口密钥，不是 QQ AppSecret 或 AccessToken：

{
  "action": "qq_generate_share_url",
  "params": { "callbackData": "my-dice" }
}

成功响应的 data 保留平台返回的数据。分享链接位于平台响应的 data.url；因此在后台接口的成功响应中为 data.data.url。调用失败时返回可读错误；未授权、限流和业务错误不会被当成成功。该入口仅允许列出的动作，不提供任意 URL 或 HTTP 方法代理。

群／用户标识可使用当前机器人账号的 OpenID，或已经关联的裸公共群号／用户号。不同机器人 AppID 的端点不能混用。涉及成员批量操作时每次最多 20 人；入群申请分页每页最多 50，群黑名单分页每页最多 100。

{
  "action": "qq_input_notify",
  "params": { "userOpenId": "用户OpenID", "seconds": 30, "msg_id": "收到的消息ID" }
}

仅适用于私聊，持续时间为 1–60 秒。普通消息的 msg_id 与事件回复的 event_id 二选一。

以下是 Dice!Next 新增的原生钩子，不是对 SealDice 标准接口的声明。原有海豹风格事件接口保持原有签名。

ext.onQQInteraction = (ctx, event, msg) => {
  // event.interaction_id 是互动回应 ID；不要与外层 event_id 混用。
  // event.interaction_data.resolved 保留按钮、菜单、反馈或授权数据。
  if (event.interaction_type === 11) {
    seal.replyToSender(ctx, msg, '已收到按钮操作。');
  }
};

ext.onQQSubscriptionStatus = (ctx, event, msg) => {
  // event.subscription_results 保留模板、允许/拒绝、订阅 ID 和时间。
};

ext.onQQOfficialEvent = (ctx, event, msg) => {
  // 其他官方非消息事件，例如好友删除和频道资料变更。
};

event.groupId、userId、operatorId 使用统一后的公共身份；event.data 保留平台事件体。互动、授权通知不提升操作者权限，钩子仍遵守原有的插件启停和群开关。

把插件 ruleTemplate 里的 alias、setConfig 翻译过来，再加一个关键的 commands.disable：

{
  "name": "最终物语",
  "set": { "keys": ["fu", "最终物语"], "diceSides": 6 },
  "alias": {
    "敏捷骰面初始值": ["dex", "dexterity", "敏捷"],
    "力量骰面初始值": ["mig", "might", "力量"],
    "生命值": ["hp", "hit point", "hit points"],
    "物防": ["pd", "df", "defense", "物理防御"]
  },
  "commands": { "disable": ["rc", "ri", "buff", "ds"] },
  "help": { "最终物语": "Fabula Ultima 规则。.set fu 切换…" }
}

- set.diceSides: 6 ← setConfig.diceSides：激活后本群默认切 6 面骰。
- alias ← ruleTemplate.alias：直接照抄。这样 .st mig=8 会自动识别成「力量骰面初始值」，.st dex=10 识别成「敏捷骰面初始值」。
- commands.disable ← 这是把海豹插件接进来的关键一步，下面专门讲。

把插件里的 rcHelp / buffHelp … 字符串收成词条，玩家 .help rc、.help buff 即可查：

{
  "mod": "最终物语速查",
  "author": "Mint Cider",
  "helpdoc": {
    "rc": "最终物语检定：.rc ++…",
    "buff": "最终物语异常状态：.buff  / .buff add|del …",
    "命刻": "&clk"
  }
}

（"命刻": "&clk" 表示「命刻」是「clk」的别名词条。）

规则文件是普通 JSON，定义这套规则系统的属性、指令、默认骰等。激活后优先级高于内置指令，同名帮助词条也覆盖内置。

{
  "name": "我的克苏鲁扩展",
  "id": "my-coc-extension",
  "set": {
    "keys": ["mycoc"],
    "diceSides": 100
  },
  "alias": {
    "侦查": ["侦察", "观察", "spot"],
    "力量": ["str", "STR"]
  },
  "computed": {
    "理智上限": "99 - 克苏鲁神话"
  },
  "commands": {
    "disable": ["jrrp"],
    "alias": { "检定": "ra" },
    "add": {
      "稳定": {
        "output": "{nick} 进行稳定判定：1d100={1d100}",
        "help": ".稳定 —— 进行一次稳定判定"
      }
    }
  },
  "help": {
    "本规则": "这是我的克苏鲁扩展，包含……"
  }
}

